import torch
def generate(model, tokenizer, user_prompt, max_new_tokens=20, no_repeat_ngram_size=4, position_ids=None, **args):
  with torch.no_grad():
    torch.cuda.empty_cache()
    inputs = tokenizer(user_prompt, return_tensors="pt", padding=True, truncation=True).to(device)
    outputs = model.generate(**inputs,  use_cache=True, bad_words_ids=starcoder2_bad_words if tokenizer== starcoder2_tokenizer else None, no_repeat_ngram_size=no_repeat_ngram_size, repetition_penalty=1.2, max_new_tokens=max_new_tokens, **args)
    torch.cuda.empty_cache()
    output =  tokenizer.batch_decode(outputs)
    return output



