def qet_query(answer):
    answer_arr = answer.split(". ")
    for _ in range(3):
      if len(answer_arr) < 5:
          query2 = [q for q in instruction_gen_tokenizer.batch_decode(instruction_gen_model.generate(**instruction_gen_tokenizer(". ".join(answer_arr), max_length=512, truncation=True, return_tensors="pt").to(device), max_length=512,   min_length=1, ), skip_special_tokens=True) if 'TypingMind.com' not in q and 'ChatHub' not in q]
          if not query2: continue
          query2 = query2[0].strip()
      elif len(answer_arr) < 10:
          ans1 = ". ".join(answer_arr[:5])+"."
          ans2 = ". ".join(answer_arr[5:])+"."
          query2 = [q for q in instruction_gen_tokenizer.batch_decode(instruction_gen_model.generate(**instruction_gen_tokenizer([ans1, ans2], max_length=512, padding=True, truncation=True, return_tensors="pt").to(device), max_length=512, min_length=1,  ), skip_special_tokens=True) if 'TypingMind.com' not in q and 'ChatHub' not in q]
          query3 = []
          for q in query2:
            q2 = ""
            for s in q.split(". "):
              if any(s in q3 for q3 in query3):
                continue
              q2 += ". "+s
            q2 = q2.strip()
            q2 = q2.lstrip(".")
            if q2:
              query3.append(q2)
          if not query3: continue
          query2 = "\n".join([query3[0]]+[q.replace(" a ", " the ").replace(" an ", " the ") for q in query3[1:] if "following" not in q and " this " not in q and " summar" not in q and "grammar" not in q])
      else:
          ans1 = ". ".join(answer_arr[:5])+"."
          ans2 = ". ".join(answer_arr[5:10])+"."
          ans3 = ". ".join(answer_arr[-10:])+"."
          query2 = [q for q in instruction_gen_tokenizer.batch_decode(instruction_gen_model.generate(**instruction_gen_tokenizer([ans1, ans2, ans3], max_length=512, padding=True, truncation=True, return_tensors="pt").to(device), max_length=512,   min_length=1, ), skip_special_tokens=True) if 'TypingMind.com' not in q and 'ChatHub' not in q]
          query3 = []
          for q in query2:
            q2 = ""
            for s in q.split(". "):
              if any(s in q3 for q3 in query3):
                continue
              q2 += ". "+s
            q2 = q2.strip()
            q2 = q2.lstrip(".")
            if q2:
              query3.append(q2)
          if not query3: continue
          query2 = "\n".join([(query3[0]).strip()]+[q.replace(" a ", " the ").replace(" an ", " the ").strip() for q in query3[1:] if "following" not in q and " this " not in q and " summar" not in q and "grammar" not in q])
      if ("following" in query2 or " summar" in query2 or "grammar" in query2):
        continue

    return query2

