from fast_pytorch_kmeans import KMeans

def is_contiguous(arr):
  """determine if the ints in the arr are continguous (1, 2, 3, 4) or not"""
  start = None
  prev = None
  contiguous=True
  for i in arr:
    if start is None:
      start = i
    if prev is None or i == prev+1:
      prev = i
      continue
    contiguous = False
    break
  return contiguous, start, i+1


def get_np_memmap_length(filename, shape, dtype=np.float32, ):
  """find the number of items in the mmap"""
  if not os.path.exists(filename):
    return shape[0]
  else:
    size = np.dtype(dtype).itemsize*np.prod(shape[1:])
    return int(os.path.getsize(filename)/size)

def np_memmap(filename, embeds=None, idxs=None, shape=None, dtype=np.float32, offset=0, order='C' ):
  """
  convienence funciton to create, set and return items from a mmap file. useful for dealing with embeddings that are larger than RAM.
  create a mmap if one doesn't exist. insert embeds into the mmap. if idxs are passed in, then set the embeds for just those idxs.
  if no embeds is passed in, then return just idxs items from the mmap file, or the whole mmap file otherwise."""

  if not filename.endswith(".mmap"):
    filename = filename+".mmap"
  if os.path.exists(filename):
    mode = "r+"
  else:
    mode = "w+"
  if shape is None and embeds is not None:
    shape = embeds.shape
  if not shape: shape = [0, 1]
  memmap = np.memmap(filename, mode=mode, dtype=dtype, shape=tuple(shape), offset=offset, order=order)
  cont = False
  if idxs:
    cont, start, end = is_contiguous(idxs)
  if embeds is None:
    if cont:
      return memmap[start:end]
    elif idxs:
      return memmap[idxs]
    else:
      return memmap

  if tuple(shape) == tuple(embeds.shape):
    memmap[:] = embeds
  elif cont:
    memmap[start:end] = embeds
  elif idxs:
    memmap[idxs] = embeds
  else:
    memmap[:] = embeds

  return memmap



def _cluster_one_batch(true_k,  spans, clusters, span2cluster_label, level, cluster_embeddings, min_overlap_merge_cluster, device):
    """
    internal function used to cluster one batch of embeddings. returns the new_labels and changes clusters and span2cluster_label
    """
    with torch.no_grad():
      embeddings = torch.from_numpy(cluster_embeddings)
      km = KMeans(n_clusters=true_k, mode='cosine')
      km_labels = km.fit_predict(embeddings.to(device=device, dtype=torch.float32)).tolist()
      embeddings = None
      # labels start from 1km_labels = [l.item() for l in km_labels.cpu()
    if not clusters:
      label2label = {}
      for span, label in zip(spans, km_labels):
        label = (label, level)
        if label not in label2label:
          label2label[label] = (span[0], level)
        label = label2label[label]
        clusters[label] = clusters.get(label, [])+[span]
        span2cluster_label[span] = label
      return list(clusters.keys())

    tmp_cluster = {}
    for span, label in zip(spans, km_labels):
      tmp_cluster[label] = tmp_cluster.get(label, [])+[span]
    new_labels = []
    #print (len(tmp_cluster), tmp_cluster)
    #create unique (level, id) labels and merge if necessary
    for a_cluster in tmp_cluster.values():
      for span in a_cluster:
        need_labels = [span for span in a_cluster if span not in span2cluster_label or span2cluster_label[span][1] != level]
        cluster_labels =[span2cluster_label[span] for span in a_cluster if span in span2cluster_label and span2cluster_label[span][1] == level]
        if not need_labels: continue
        if not cluster_labels:
          label = (span[0], level)
        else:
          most_common = Counter(cluster_labels).most_common(1)[0]
          if most_common[1] < min_overlap_merge_cluster:
            label = (span[0], level)
          else:
            label = most_common[0]
        new_labels.append(label)
        for span in need_labels:
          clusters[label] = clusters.get(label, [])+[span]
          span2cluster_label[span] = label
    return new_labels

def create_hiearchical_clusters(mmap_file, embed_dim, mmap_dtype=np.float32, force_recluster_idxs=None, mmap_len=None, max_level=4, max_cluster_size=200, min_overlap_merge_cluster=2, prefered_leaf_node_size=None, kmeans_batch_size=250000, \
                                use_tqdm=False, step_size_percentage=0.7, max_num_retries_cluster=3, recluster_threshold=0.5, device="cuda:0", clusters=None, span2cluster_label=None):
  """
  Incremental aglomerative hiearchical clustering from ALL embeddings stored in a mmap file. Will cluster new items added to the file.
  with 4 levels, and each node containing 200 items, we can have up to 1.6B items approximately
  span2cluster_label maps a child span to a cluster label. spans are of the form (index into mmap, hiearchical level).
  clusters maps a cluster label  => list of child spans.
  cluster labels are just the first span in the child span list.
  when we use the term 'idx', we normally refer to the index in an embedding file and we refer to spans as the tuples
  :arg mmap_file                      Name of file where the data is stored
  :arg embed_dim                      The dimension of the vector for the emebdding
  :arg mmap_dtype                     The dtype for the mmap file
  :arg mmap_len                       Number of items in mmap_file
  :arg force_recluster_idxs:          Optioal. if provided, the particular embedding idx that will be clustered in this call.
  :arg max_level:                     The maximum level of the cluster hiearchy.
  :arg max_cluster_size:              The maximum size of any particular cluster.
  :arg min_overlap_merge_cluster.     When incremental clustering, the minimum overlap between one cluster and another before merging them.
  :arg kmeans_batch_size:             The size of each batch of embeddings that are kmean batched.
  :arg use_tqdm:                      Whether to report the progress of the clustering.
  :arg device:                        The device on which to run the clustering
  """
  dtype = mmap_dtype
  if mmap_len is None:
    mmap_len = get_np_memmap_length(mmap_file, [0, embed_dim], dtype=dtype)
  if clusters is None:
    clusters = {}
  if span2cluster_label is None:
    span2cluster_label = {}
  if force_recluster_idxs:
    force_recluster_idxs = set(force_recluster_idxs)
  else:
    force_recluster_idxs = ()
  already_clustered = set([span[0] for span in span2cluster_label if span[1] == 0 and span[0] not in force_recluster_idxs])
  idxs = []
  if force_recluster_idxs:
    idxs = list(force_recluster_idxs)
    force_recluster_idxs = None
  idxs.extend([idx for idx in range(mmap_len) if idx not in already_clustered])
  if not idxs: return
  already_clustered = list(already_clustered)
  if len(already_clustered)  > int(.5*kmeans_batch_size):
    idxs.extend(random.sample(already_clustered, int(.5*kmeans_batch_size)))
  else:
    idxs.extend(already_clustered)
  already_clustered =  None
  idxs.extend([span[0] for span in span2cluster_label if span[1] != 0])
  idxs = list(set(idxs))
  random.shuffle(idxs)
  if not prefered_leaf_node_size:
    prefered_leaf_node_size= int (max_cluster_size*.7)
  for level in range(max_level):
    all_spans = [(idx, level) for idx in idxs]
    len_spans = len(all_spans)
    # we are going to do a minimum of 3 times in case there are de-clustered items
    # from previous iterations.
    step_size = int(step_size_percentage*kmeans_batch_size)
    num_times = max(max_num_retries_cluster,math.ceil(len_spans/step_size))
    if use_tqdm:
      num_times2 = tqdm.tqdm(range(num_times))
    else:
      num_times2 = range(num_times)
    for times in num_times2:
        max_rng = min(len_spans, step_size)
        #create the next batch to cluster
        spans = all_spans[:max_rng]
        not_already_clustered = [span for span in all_spans[:max_rng-step_size] if span not in span2cluster_label]
        if len(not_already_clustered) > int(.5*kmeans_batch_size):
          spans.extend(random.sample(not_already_clustered, int(.5*kmeans_batch_size)))
        else:
          spans.extend(not_already_clustered)
        if len(spans) == 0: break
        already_clustered = [span for span in all_spans[:max_rng-step_size] if span in span2cluster_label]
        if len(already_clustered)  > int(recluster_threshold*kmeans_batch_size):
          spans.extend(random.sample(already_clustered, int(.5*kmeans_batch_size)))
        else:
          spans.extend(already_clustered)
        embedding_idxs = [span[0] for span in spans]
        #do kmeans clustering in batches with the embedding indexes
        if level == 0:
          true_k = int(len(embedding_idxs)/prefered_leaf_node_size)
        else:
          true_k = int(len(embedding_idxs)/max_cluster_size)
        cluster_embeddings = np_memmap(mmap_file, shape=[mmap_len, embed_dim], idxs=embedding_idxs, dtype=dtype)
        new_labels = _cluster_one_batch(true_k,  spans, clusters, span2cluster_label, level, cluster_embeddings, min_overlap_merge_cluster, device)
        if not new_labels: break
        need_more = False
        if times <= num_times-2:
          for label in new_labels:
            if len(clusters[label]) < prefered_leaf_node_size:
              del clusters[label]
              need_more = True
        if not need_more: break
    # prepare data for next level clustering
    idxs  = [val[0][0] for key, val in clusters.items() if key[1] == level]
    if len(idxs ) < max_cluster_size: break
  return (clusters, span2cluster_label)

